for (const item of items) {
  const candidate = item.json;
  const role = candidate.position || "Software Engineer";
  const skills = candidate.claimed_skills;
  const background = candidate.past_company_type;

  const systemPrompt = `
Role: You are a Senior Technical Interviewer for a ${role} position.
Your goal is to validate the technical depth of a candidate named ${candidate.candidate_name}.

CONTEXT:
The candidate claims expertise in: ${skills}.
However, their background is from: ${background}.

TASK:
Generate exactly ONE advanced technical interview question (Studi Kasus) to verify whether they truly understand the internal workings of the tech stack or only have surface-level knowledge.
Focus on a troubleshooting scenario (for example: a pod stuck in CrashLoopBackOff in production) and architectural trade-offs.

IMPORTANT:
- The question must be challenging but professional.
- Keep the whole output under 1200 characters.
- Provide the output in INDONESIAN language.
- Do not use markdown symbols such as ** or _ (plain text only).

OUTPUT FORMAT (plain text):
Topik: [Nama Topik]
Pertanyaan: [Studi Kasus Spesifik]
Ekspektasi Jawaban Senior: [Poin Kunci]
`;

  item.json.llm_prompt = systemPrompt;
}
return items;

const aiQuestion = items[0].json.text;
let candidateName = "";
try {
  candidateName = $('Loop Over Items').item.json.candidate_name;
} catch (e) {
  candidateName = $('Loop Over Items').first().json.candidate_name;
}

let mockAnswer = "";
if (candidateName.includes("Budi")) {
  mockAnswer = "Untuk masalah CrashLoopBackOff, saya akan cek logs pod pakai kubectl logs, lalu describe pod untuk lihat events. Biasanya karena configmap salah atau app panic saat startup.";
} else {
  mockAnswer = "Saya biasanya restart servernya pak. Kalau masih error saya install ulang Kubernetesnya.";
}

return [
  {
    json: {
      question: aiQuestion,
      candidate_answer: mockAnswer,
      candidate_name: candidateName
    }
  }
];

const data = items[0].json;

const prompt = `
ROLE: You are a Senior Hiring Manager.
TASK: Evaluate the candidate's answer based on the technical question provided.

DATA:
- Candidate Name: ${data.candidate_name}
- Question Given: "${data.question.substring(0, 600)}"
- Candidate Answer: "${data.candidate_answer}"

INSTRUCTION:
Give a score (0-100) and a brief critique stating whether the answer shows technical depth or is only generic.
- If the answer shows deep troubleshooting steps (logs, events, root cause), give a HIGH score.
- If the answer is generic (restart server, reinstall), give a LOW score (Red Flag).
- Decision: LOLOS if score >= 70, otherwise GAGAL.

OUTPUT FORMAT (Indonesian, plain text, no markdown symbols):
Penilaian untuk ${data.candidate_name}
--------------------------
Skor: [0-100]
Analisa: [Penjelasan singkat 1 kalimat]
Keputusan: [LOLOS / GAGAL]
`;

return [
  {
    json: {
      eval_prompt: prompt,
      candidate_name: data.candidate_name
    }
  }
];

